DO $$
BEGIN
  IF (SELECT count(*) FROM murdoku_case_clue_updates) <> 15 THEN
    RAISE EXCEPTION 'Expected 15 case clue updates';
  END IF;
END;
$$;

-- Update each case: keep incident clue and append the single clue per character
UPDATE public.murdoku_cases c
SET difficulty = u.difficulty,
    content = jsonb_set(
      c.content,
      '{clues}',
      jsonb_build_array(
        COALESCE(
          (
            SELECT clue.value
            FROM jsonb_array_elements(c.content->'clues') AS clue(value)
            WHERE clue.value->>'id' = 'incident'
            LIMIT 1
          ),
          jsonb_build_object(
            'id', 'incident',
            'type', 'fact',
            'text', COALESCE(c.title_i18n, jsonb_build_object('es', c.title))
          )
        )
      ) || u.char_clues,
      true
    ),
    updated_at = now()
FROM murdoku_case_clue_updates u
WHERE c.id = u.case_id;

DROP TABLE murdoku_case_clue_updates;
